/*
 * Copy-first port of node_modules/@salesforce/retail-react-app/app/components/product-item/index.jsx
 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
 * plan step 2.1). Zero functional diff at that step — TypeScript annotations, the import path
 * rewrites documented below, and a temporary `[overrides]` console.log marker (verified live
 * against three real surfaces per the plan's copy-first stop, then removed) were the only
 * changes; styling/behaviour changes are this commit (plan step 2.2, see below), not that one.
 *
 * Import path rewrites, per .claude/rules/overrideStyling.md's "Importing an already-overridden
 * component from a new component":
 * - `item-variant` / `item-variant/item-image` / `item-variant/item-name` /
 *   `item-variant/item-attributes` / `item-variant/item-price`: this repo overrides all five
 *   (SFCC-270, this same commit), so these are relative imports rather than the base
 *   `@salesforce/retail-react-app/...` path — a base-path import here would silently exercise the
 *   unstyled base components in Storybook/Vitest instead of these overrides.
 * - `./bonus-product-quantity` / `./product-quantity-picker`: same reasoning, both overridden in
 *   this same commit, in this same folder.
 * - `responsive` (`HideOnDesktop`/`HideOnMobile`): also already overridden in this repo
 *   (overrides/app/components/responsive/index.tsx) — and not just a styling port, a genuine
 *   behavioural difference (it moves the mobile/desktop split to Chakra's `md` breakpoint instead
 *   of the base's `lg`) — so this is rewritten to a relative import too, for the same reason.
 * - `shared/ui`, `loading-spinner`, `utils/utils`, and the `app/hooks` barrel (`useCurrency`/
 *   `useDerivedProduct`) are NOT overridden anywhere in this repo (verified by directory listing
 *   at time of writing) — these stay on the base `@salesforce/retail-react-app/...` path, since
 *   there is no local override to redirect to.
 *
 * `SfccProduct` is kept as `any` with a named alias rather than a structural type invented from
 * usage — this package ships no TypeScript types for this shape, matching the same documented gap
 * at overrides/app/components/product-view/index.tsx:136-151.
 *
 * SFCC-270 (plan step 2.2): restyled to the Figma cart-item spec via product-item.css.ts's
 * `ZimmCartItem` recipe (`row`/`details`/`info` parts, applied through `sx` — see that recipe's
 * own docblock for why `sx`, not `__css`, is required on a plain Flex/Stack here). The image's
 * own default width moved out of this file entirely — item-image.tsx now supplies its own
 * responsive default via item-variant.css.ts's `image` part, so the `mr`-based gap this file
 * used to add is replaced by the `row` part's own Figma-specified `gap`.
 * `CartItemVariantAttributes` now also renders with `combineAttributeValues`, per the Figma
 * spec's single "colour, size" string (see that component's own file). The two `display={[...]}`
 * responsive-array primaryAction visibility toggles are replaced with this file's own already-
 * imported `HideOnMobile`/`HideOnDesktop` (both already used here for `deliveryActions`) — the
 * original arrays split at Chakra's default `sm` (480px), one breakpoint earlier than this
 * file's own `md` (768px) split everywhere else; no Figma value distinguishes this, so it is
 * unified to the same `md` split as the rest of this file rather than preserved as a second,
 * unexplained breakpoint — flagged in this build's report as a disclosed interpretation, not a
 * tested requirement.
 *
 * Gift-card *detection* is still NOT implemented — unchanged finding from the prior round: no
 * real signal for "this line item is a digital gift card" exists anywhere in this codebase or
 * the commerce SDK types at time of writing (`GiftCertificateItem` exists in the SDK but is a
 * structurally different, wholly separate basket line-item shape that this component's own
 * render tree — `useDerivedProduct`, `ItemVariantProvider`'s `SfccProduct` shape — is not built
 * to receive at all). That finding stands as-is; it was independently confirmed by two separate
 * reviewers in the prior round and is not re-litigated here.
 *
 * SFCC-270 round 2 rework: the *capability* half is now built. `hideStepperAndActions` (optional,
 * defaults falsy so every existing caller is unaffected) suppresses the quantity stepper
 * (BonusProductQuantity/ProductQuantityPicker) and every actions surface (primaryAction,
 * secondaryActions, deliveryActions) when true, per .claude/session-notes.md §11.2's gift-card
 * variant note ("no stepper, no actions ... build ZimmCartItem with the stepper and actions row
 * optional"). Nothing else in this component's render tree branches on it — the 5-field
 * label/value block that same note describes for a real gift-card line item is not built here,
 * and remains for whichever future commit ends up owning real gift-card detection.
 *
 * SFCC-795 (plan step 3.2): `message` (optional, prop-driven) renders a ZimmInlineMessage between
 * the quantity stepper and the actions row, per .claude/session-notes.md §11.2 ("inline message
 * (error/warning) sits between the stepper and the actions"). This component does not itself
 * determine OOS/partial-OOS/unavailable/max-quantity state — OOS/partial-OOS detection is
 * SFCC-282's, "Unavailable" detection is SFCC-796's, both later-sprint tickets. Undefined (every
 * existing caller today) renders nothing and leaves the Item Details gap at its existing 12px
 * desktop value (`ZimmCartItem`'s `hasError` resolution prop, product-item.css.ts, derived below
 * from `message?.variant === 'error'`).
 *
 * SFCC-795 (plan step 3.3): `discountLabel` (optional, prop-driven) renders directly beneath the
 * stepper/price row, ahead of `message` above — DOM order is stepper -> discountLabel -> message
 * -> secondaryActions. Purely presentational, per session-notes.md §4's SFCC-795 decisions
 * ("Only the discount label is new, and it is purely presentational — prop-driven, storied, wired
 * when the promotions engine lands"): this component does not compute a discount percentage or
 * label itself; a caller supplies the already-resolved string once something upstream (the
 * promotions engine, and whatever cart-item mapper eventually feeds this component real basket
 * data) is wired — neither is built yet as of this commit. Undefined (every existing caller today)
 * renders nothing — no empty node is emitted. See the prop's own JSDoc below for the textStyle/
 * colour sourcing (no Figma citation exists for this specific element — confirmed by searching
 * .claude/session-notes.md directly, not assumed).
 *
 * The was/now promotional-price mechanism itself (`ListPrice` struck "Was" beside the current
 * "Now", both quantity-scaled) is NOT new at this step and is not touched here — it already lives
 * in base `display-price` (rendered via item-variant/item-price.tsx, unmodified by this commit).
 * See this component's own test file for a disclosed, verified limitation on exactly where that
 * mechanism is and isn't reachable today.
 */
import React from 'react';

// Chakra Components
import {
  Box,
  Fade,
  Flex,
  Stack,
  Text,
  useMultiStyleConfig,
} from '@salesforce/retail-react-app/app/components/shared/ui';

// Project Components
import { HideOnDesktop, HideOnMobile } from '../responsive';
import ItemVariantProvider from '../item-variant';
import CartItemVariantImage from '../item-variant/item-image';
import CartItemVariantName from '../item-variant/item-name';
import CartItemVariantAttributes from '../item-variant/item-attributes';
import CartItemVariantPrice from '../item-variant/item-price';
import LoadingSpinner from '@salesforce/retail-react-app/app/components/loading-spinner';
import BonusProductQuantity from './bonus-product-quantity';
import ProductQuantityPicker from './product-quantity-picker';
import { ZimmInlineMessage } from 'app/components/ui-kits/atoms/zimmInlineMessage';

// Hooks
import { useCurrency, useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';

const ZIMM_CART_ITEM_RECIPE = 'ZimmCartItem';

type SfccProduct = any;

type ProductItemProps = {
  product: SfccProduct;
  primaryAction?: React.ReactNode;
  secondaryActions?: React.ReactNode;
  deliveryActions?: React.ReactNode;
  onItemQuantityChange?: (quantity: number) => any;
  /**
   * Declared on the base file's propTypes but never read inside this component's own render
   * body — kept here only to mirror that declared surface one-for-one (zero functional diff,
   * SFCC-270). No return-type guarantee to derive from PropTypes.func, so typed loosely.
   */
  onAddItemToCart?: (...args: any[]) => any;
  showLoading?: boolean;
  /** Declared on the base file's propTypes but never read inside this component's own render body — see onAddItemToCart above. */
  isWishlistItem?: boolean;
  containerStyles?: Record<string, any>;
  isRemoving?: boolean;
  pickupInStore?: boolean;
  /**
   * Gift-card capability slot (SFCC-270 round 2 rework, session-notes.md §11.2): when true,
   * suppresses the quantity stepper and every actions surface (primaryAction, secondaryActions,
   * deliveryActions). Defaults falsy so every existing caller's rendering is unchanged. This
   * component does not itself detect a gift-card line item — see this file's own docblock — a
   * caller sets this explicitly once real detection exists.
   */
  hideStepperAndActions?: boolean;
  /**
   * Cart-line inline status message (SFCC-795 §11.2, plan step 3.2), rendered via
   * ZimmInlineMessage between the quantity stepper and the actions row. Presentation only — see
   * ZimmInlineMessage's own docblock: this component does not itself determine OOS/partial-OOS/
   * unavailable/max-quantity state, a caller passes the already-resolved variant + copy.
   * Undefined (the default for every existing caller) renders nothing and leaves the Item
   * Details gap at its existing 12px desktop value.
   */
  message?: {
    variant: 'error' | 'warning';
    text: string;
  };
  /**
   * Discount label rendered beneath the quantity stepper (SFCC-795 §4/§11.2, plan step 3.3),
   * e.g. "20% off applied". Purely presentational — this component does not compute or derive a
   * discount percentage/label itself; a caller passes the already-resolved string once the
   * promotions engine is wired (not yet, this sprint — see this file's own docblock). Undefined
   * (every existing caller today) renders nothing — no empty node is emitted.
   *
   * Styling: `textStyle="caption"` + `color="var(--zimm-color-text-secondary)"`, matching
   * item-variant.css.ts's `colourSize` part (the "Lilac Sand, One size" caption in this same
   * card) — the nearest existing sibling treatment. No Figma node or type style is cited
   * anywhere in .claude/session-notes.md for this specific element (searched directly for
   * "discount", not assumed) — PROVISIONAL pending UI-designer confirmation, same disclosure
   * pattern as zimmQuantityStepper.css.ts:35-38's `value` part and zimmButton.css.ts:244's
   * `BTN_MIN_WIDTH_LG`.
   */
  discountLabel?: string;
};

/**
 * Component representing a product item usually in a list with details about the product - name, variant, pricing, etc.
 * @param {Object} product Product to be represented in the list item.
 * @param {node} primaryAction Child component representing the most prominent action to be performed by the user.
 * @param {node} secondaryActions Child component representing the other actions relevant to the product to be performed by the user.
 * @param {node} deliveryActions Child component representing the delivery actions relevant to the product to be performed by the user.
 * @param {func} onItemQuantityChange callback function to be invoked whenever item quantity changes.
 * @param {boolean} showLoading Renders a loading spinner with overlay if set to true.
 * @returns A JSX element representing product item in a list (eg: wishlist, cart, etc).
 */
const ProductItem = ({
  product,
  primaryAction,
  secondaryActions,
  deliveryActions,
  // CodeRabbit (SFCC-11 cumulative review): default was `noop`, a synchronous no-op returning
  // `undefined` - but product-quantity-picker.tsx's handleQuantityChange unconditionally calls
  // `.then(...)` on this callback's return value. A caller that omits this optional prop and
  // then changes quantity would throw. This default resolves to `true` (a valid change) so the
  // `.then` chain completes normally instead.
  onItemQuantityChange = async () => true,
  showLoading = false,
  containerStyles = {},
  isRemoving = false,
  pickupInStore = false,
  hideStepperAndActions = false,
  message,
  discountLabel,
}: ProductItemProps) => {
  const { stepQuantity, showInventoryMessage, inventoryMessage, quantity, setQuantity } = useDerivedProduct(
    product,
    false,
    false,
    pickupInStore,
  );
  const { currency: activeCurrency } = useCurrency();
  // hasError drives ZimmCartItem's own Item Details gap widening (12px -> 16px desktop) — see
  // product-item.css.ts's docblock — derived from `message`, not a separate prop, so the two can
  // never disagree about whether an error-variant message is currently showing.
  const styles = useMultiStyleConfig(ZIMM_CART_ITEM_RECIPE, { hasError: message?.variant === 'error' });
  return (
    <Box position="relative" data-testid={`sf-cart-item-${product.productId ? product.productId : product.id}`}>
      <ItemVariantProvider variant={product}>
        {showLoading && <LoadingSpinner />}
        <Stack layerStyle="cardBordered" align="flex-start" {...containerStyles}>
          <Flex sx={styles.row} width="full" backgroundColor="white">
            <CartItemVariantImage />
            <Stack sx={styles.details} flex={1}>
              <Flex sx={styles.info}>
                <Stack spacing={1}>
                  <CartItemVariantName />
                  <CartItemVariantAttributes excludeBonusLabel combineAttributeValues />
                  <HideOnDesktop>
                    <Box marginTop={2}>
                      <CartItemVariantPrice align="left" currency={activeCurrency} />
                    </Box>
                  </HideOnDesktop>
                </Stack>
                {!hideStepperAndActions && deliveryActions && !product.bonusProductLineItem && (
                  <HideOnMobile>{deliveryActions}</HideOnMobile>
                )}
              </Flex>

              {!hideStepperAndActions && deliveryActions && !product.bonusProductLineItem && (
                <HideOnDesktop>{deliveryActions}</HideOnDesktop>
              )}

              <Flex align="flex-end" justify="space-between">
                <Stack spacing={1}>
                  {!hideStepperAndActions &&
                    !(isRemoving && product.bonusProductLineItem) &&
                    (product.bonusProductLineItem ? (
                      <BonusProductQuantity product={product} />
                    ) : (
                      <ProductQuantityPicker
                        product={product}
                        onItemQuantityChange={onItemQuantityChange}
                        stepQuantity={stepQuantity}
                        quantity={quantity}
                        setQuantity={setQuantity}
                      />
                    ))}
                </Stack>
                <Stack>
                  <HideOnMobile>
                    <CartItemVariantPrice currency={activeCurrency} />
                  </HideOnMobile>
                  {!hideStepperAndActions && <HideOnMobile>{primaryAction}</HideOnMobile>}
                </Stack>
              </Flex>

              {/* SFCC-795 (plan step 3.3): discount label, directly beneath the stepper/price row
                  above, ahead of the inline message below — prop-driven only, no empty node when
                  omitted. See the `discountLabel` prop's own JSDoc for the styling citation. */}
              {discountLabel && (
                <Text textStyle="caption" color="var(--zimm-color-text-secondary)" data-testid="zimm-discount-label">
                  {discountLabel}
                </Text>
              )}

              {/* SFCC-795 §11.2: sits between the stepper (above) and the actions row (the
                  existing inventory Box below, secondaryActions, and the mobile primaryAction
                  block further down) — prop-driven only, see this file's own docblock. */}
              {message && <ZimmInlineMessage variant={message.variant} text={message.text} />}

              <Box>
                {product && showInventoryMessage && (
                  <Fade in={true}>
                    <Text color="orange.600" fontWeight={600}>
                      {inventoryMessage}
                    </Text>
                  </Fade>
                )}
              </Box>

              {!hideStepperAndActions && secondaryActions}
            </Stack>
          </Flex>

          {!hideStepperAndActions && (
            <HideOnDesktop>
              <Box w={'full'}>{primaryAction}</Box>
            </HideOnDesktop>
          )}
        </Stack>
      </ItemVariantProvider>
    </Box>
  );
};

export default ProductItem;

/**
 * SFCC-270 round 2 rework, extended post-rework (found live in Storybook by Marcel, not by this
 * suite). Proves three stacked bugs are actually fixed TOGETHER, not just that the symbols were
 * added:
 *   1. `useVariationAttributes` -> `isVariantValueOrderable` (base SFCC hook, unconditional
 *      `product.variants.filter(...)`) needs `variants` to be an array on the mock product.
 *   2. `useDerivedProduct` unconditionally calls `useSelectedStore()`, which throws without a
 *      real `StoreLocatorProvider` ancestor.
 *   3. `item-attributes.tsx`'s `useCurrentBasket()` call has its own separate transitive chain
 *      (`useSFPayments` -> `useAppOrigin` -> `useOrigin`) that calls the SDK's
 *      `useServerContext()` and destructures `res` from it unconditionally, before `useOrigin`'s
 *      own `typeof window !== 'undefined'` branch (which never touches `res`) is reached. This
 *      file previously mocked `useCurrentBasket` away entirely, which hid this bug completely —
 *      unmocked now so this suite actually exercises the real chain. `ServerContext.Provider`
 *      with `value={{}}` matches exactly what the real app's own browser bootstrap supplies
 *      client-side (`ssr/browser/main.js`'s `OuterApp`) — confirmed by reading that file.
 *
 * Deliberately does NOT use index.test.tsx's harness — that file mocks the whole
 * `@salesforce/retail-react-app/app/hooks` barrel's `useDerivedProduct`, which would hide both
 * bugs this file exists to catch. This renders through the real, unmocked `useDerivedProduct` ->
 * `useVariationAttributes` -> `isVariantValueOrderable` / `useSelectedStore` chain, with a real
 * `StoreLocatorProvider` ancestor.
 *
 * `useMultiSite` and `useCurrency` are still mocked, for a reason that has nothing to do with
 * this build's own logic: `@salesforce/retail-react-app/app/contexts` (the barrel both
 * `MultiSiteProvider`/`CurrencyProvider` and `use-multi-site.js`/`use-currency.js` resolve
 * through) is a `.js` file containing inline JSX, which Vite's transform cannot parse as a
 * plain `.js` file — confirmed empirically (this file's first draft imported `MultiSiteProvider`
 * from that barrel directly and vitest failed at import-analysis on
 * `app/contexts/index.js:49`, not at any assertion). This is the same parse failure
 * item-variant/index.test.tsx's own docblock already documents and works around by mocking
 * `use-multi-site` instead of using a real `MultiSiteProvider`; extended here to `useCurrency`
 * for the same reason. `StoreLocatorProvider` itself is real: `use-selected-store.js` and
 * `store-locator-provider.jsx` both import `StoreLocatorContext` via that file's own direct path
 * (`.../app/contexts/store-locator-provider`), never through the barrel, so it never hits this
 * parse wall — confirmed by reading both files' imports, not assumed.
 *
 * Two more pragmatic mocks, both explained inline at their own `vi.mock`/`beforeEach`: `useStores`
 * (an unrelated dual-module-instance QueryClient issue, not this build's own code) and a
 * `window.matchMedia` polyfill (jsdom has none; item-price.tsx's `useBreakpointValue` needs it —
 * the same pre-existing gap and fix product-item/index.test.tsx's own `beforeEach` already uses).
 * Neither affects what this file actually proves: that a real `StoreLocatorProvider` ancestor and
 * an array-valued `variants` together stop the render from throwing.
 */
import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { CommerceApiProvider } from '@salesforce/commerce-sdk-react';
import { StoreLocatorProvider } from '@salesforce/retail-react-app/app/contexts/store-locator-provider';
import { ServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/contexts';
import theme from 'app/theme';
import ProductItem from '.';

vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
  default: vi.fn(() => ({ site: { id: 'ZimmermannAU' }, buildUrl: (path: string) => path })),
}));

// Cannot use this factory's `importOriginal` here: it resolves the barrel itself
// (`app/hooks/index.js`), which re-exports `useCurrency` from `use-currency.js`, which imports
// `CurrencyContext` from the broken `app/contexts` barrel — so `importOriginal()` transitively
// hits the same parse wall as importing `MultiSiteProvider` does (confirmed empirically: this
// was the first thing tried here, and it failed at the identical `app/contexts/index.js:49`
// parse error). `vi.importActual` on `use-derived-product`'s own direct sub-path sidesteps it —
// that file's own dependency chain never touches `app/contexts` (confirmed by grepping it and
// every hook it imports).
vi.mock('@salesforce/retail-react-app/app/hooks', async () => {
  const { useDerivedProduct } = await vi.importActual<
    typeof import('@salesforce/retail-react-app/app/hooks/use-derived-product')
  >('@salesforce/retail-react-app/app/hooks/use-derived-product');
  return {
    useCurrency: () => ({ currency: 'AUD', setCurrency: vi.fn() }),
    useDerivedProduct,
  };
});

// Same fix as product-item/index.test.tsx's own: PromoPopover imports the base SFCC icons
// barrel, which has a top-level side effect that throws under Vitest (testing.md's documented
// ZimmIcon gap, same root cause via a different import path).
vi.mock('@salesforce/retail-react-app/app/components/promo-popover', () => ({
  default: ({ children }: { children?: React.ReactNode }) => <>{children}</>,
}));

// SFCC-795 rework (ZimmInlineMessage's warning icon): ProductItem -> ZimmInlineMessage ->
// ZimmIcon -> the base SFCC icons barrel is a new static import chain as of this rework, hitting
// the identical top-level-side-effect crash the mock above already works around for
// PromoPopover's own path to that same barrel. Neither test below passes a `message` prop, so the
// icon never needs to render distinguishably — testing.md's own documented canonical form
// (`ZimmIcon: () => null`) applies directly, no props need forwarding.
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
  ZimmIcon: () => null,
}));

// `useStores` is mocked too (in addition to usePromotions/useProducts/useProduct, needed for the
// same reason as product-item/index.test.tsx's own): the REAL `useSelectedStore` (unmocked, the
// actual thing this file proves doesn't throw) calls it internally, and the real `useStores` hit
// an unrelated environment issue here — `@tanstack/react-query`'s `useQueryClient()` not finding
// this file's own `QueryClientProvider` (a dual-module-instance style mismatch, not anything this
// build's own code controls). Mocking only `useStores` still exercises `useSelectedStore`'s own
// real body — including the `useContext(StoreLocatorContext)` throw-if-missing check this file
// exists to prove no longer throws — while sidestepping that unrelated plumbing issue.
vi.mock('@salesforce/commerce-sdk-react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@salesforce/commerce-sdk-react')>();
  return {
    ...actual,
    usePromotions: () => ({ data: undefined }),
    useProducts: () => ({ data: undefined, isLoading: false }),
    useProduct: () => ({ data: undefined, isLoading: false }),
    useStores: () => ({ data: undefined, isLoading: false }),
    // Same dual-module-instance QueryClient issue as useStores above, surfacing here now that
    // useCurrentBasket (unmocked, see this file's own docblock) calls this for real internally.
    useCustomerBaskets: () => ({ data: undefined, isLoading: false }),
  };
});

const storyQueryClient = new QueryClient({
  defaultOptions: { queries: { retry: false, refetchOnWindowFocus: false } },
});

// `useStores` (called for real inside the real `useSelectedStore`, unmocked above) is left real
// too — it resolves with `enabled: false` (no selectedStoreId in this jsdom's empty
// localStorage), so it registers a disabled query and never actually fetches, matching
// index.stories.tsx's own documented reasoning for its inert CommerceApiProvider/proxy setup.
const renderWithStoryProviders = (ui: React.ReactElement) =>
  render(
    <ServerContext.Provider value={{}}>
      <ChakraProvider theme={theme}>
        <MemoryRouter>
          <QueryClientProvider client={storyQueryClient}>
            <CommerceApiProvider
              clientId="00000000-0000-0000-0000-000000000000"
              organizationId="f_ecom_storybook_001"
              shortCode="storybook"
              siteId="ZimmermannAU"
              locale="en-AU"
              currency="AUD"
              proxy="https://storybook.invalid/mobify/proxy/api"
              redirectURI="https://storybook.invalid/callback"
              disableAuthInit
              silenceWarnings
            >
              <StoreLocatorProvider config={{ defaultCountryCode: 'AU', defaultPostalCode: '2000' }}>
                <IntlProvider locale="en-AU" defaultLocale="en-AU">
                  {ui}
                </IntlProvider>
              </StoreLocatorProvider>
            </CommerceApiProvider>
          </QueryClientProvider>
        </MemoryRouter>
      </ChakraProvider>
    </ServerContext.Provider>,
  );

// Mirrors index.stories.tsx's own MOCK_LINE_ITEM shape, including the round 2 `variants: []` fix.
const MOCK_LINE_ITEM = {
  itemId: 'a1b2c3d4e5f6a1b2c3d4e5f6',
  productId: '25595021M',
  id: '25595021M',
  productName: 'Lilac Sand Silk Midi Dress',
  name: 'Lilac Sand Silk Midi Dress',
  price: 495,
  priceAfterItemDiscount: 495,
  pricePerUnit: 495,
  quantity: 1,
  stepQuantity: 1,
  minOrderQuantity: 1,
  imageGroups: [
    {
      viewType: 'small',
      images: [{ alt: 'Lilac Sand Silk Midi Dress', link: 'https://example.invalid/lilac-sand.jpg' }],
    },
  ],
  variationAttributes: [
    { id: 'color', name: 'Colour', values: [{ value: 'JJ5FUXX', name: 'Lilac Sand', orderable: true }] },
    { id: 'size', name: 'Size', values: [{ value: 'ONESIZE', name: 'One Size', orderable: true }] },
  ],
  variationValues: { color: 'JJ5FUXX', size: 'ONESIZE' },
  variants: [],
};

describe('ProductItem — Storybook story render (SFCC-270 round 2)', () => {
  // jsdom has no matchMedia implementation, and item-price.tsx's `isDesktop` uses
  // useBreakpointValue internally, which calls it — unrelated to either bug this file exists to
  // catch, same pre-existing gap and same per-file polyfill product-item/index.test.tsx's own
  // beforeEach already uses (not a change to the frozen vitest.setup.ts).
  beforeEach(() => {
    Object.defineProperty(window, 'matchMedia', {
      writable: true,
      value: vi.fn().mockImplementation((query: string) => ({
        matches: false,
        media: query,
        onchange: null,
        addListener: vi.fn(),
        removeListener: vi.fn(),
        addEventListener: vi.fn(),
        removeEventListener: vi.fn(),
        dispatchEvent: vi.fn(),
      })),
    });
  });

  test('Default-equivalent: renders through the real, unmocked useDerivedProduct/useSelectedStore chain without throwing', () => {
    expect(() =>
      renderWithStoryProviders(
        <ProductItem product={MOCK_LINE_ITEM} primaryAction={<button type="button">Remove</button>} />,
      ),
    ).not.toThrow();

    expect(screen.getByRole('heading', { level: 2 })).toHaveTextContent('Lilac Sand Silk Midi Dress');
  });

  test('GiftCard-equivalent: hideStepperAndActions renders through the real chain without throwing, and hides the actions', () => {
    expect(() =>
      renderWithStoryProviders(
        <ProductItem
          product={MOCK_LINE_ITEM}
          primaryAction={<button type="button">Remove</button>}
          secondaryActions={<button type="button">Edit</button>}
          hideStepperAndActions
        />,
      ),
    ).not.toThrow();

    expect(screen.queryByRole('button', { name: 'Remove' })).not.toBeInTheDocument();
    expect(screen.queryByRole('button', { name: 'Edit' })).not.toBeInTheDocument();
  });
});

