/**
 * Commerce/ProductItem — Storybook stories for the cart line-item shell (SFCC-270, plan
 * step 2.2), restyled to the Figma cart-item spec.
 *
 * Providers supplied by .storybook/preview.tsx: IntlProvider, ChakraProvider.
 * This file adds its own inert provider stack, matching product-view/index.stories.tsx's own
 * documented pattern (see that file for the full rationale):
 *   MemoryRouter — item-name.tsx's <Link> (react-router-dom) and useMultiSite (via
 *     MultiSiteProvider below) both need Router/site context.
 *   MultiSiteProvider — useMultiSite (item-name.tsx's <Link>'s buildUrl, and
 *     StoreLocatorProvider below, which reads the current site to namespace its localStorage key).
 *   StoreLocatorProvider — `useDerivedProduct` (via item-price.tsx/item-attributes.tsx's own
 *     transitive dependency chain) unconditionally calls `useSelectedStore()`
 *     (`use-selected-store.js`), which throws `'useSelectedStore must be used within a
 *     StoreLocatorProvider'` with no Provider present — round 2 rework fix, confirmed by reading
 *     that hook's source, not assumed. Nested inside MultiSiteProvider (its own body calls
 *     useMultiSite()), outside CommerceProviders (its one consumer, `useSelectedStore`'s internal
 *     `useStores` call, resolves with `enabled: false` here since no story sets a selected store
 *     in localStorage, so it never actually needs Commerce context — but this file nests it
 *     inside CommerceProviders anyway for a single consistent provider order). `config={{}}` is a
 *     deliberately empty stand-in — no story here drives real store-locator state, so there is no
 *     real config value to supply; PropTypes will warn on the missing required fields, which is
 *     inert noise, not a render failure.
 *   CommerceApiProvider + QueryClientProvider — item-attributes.tsx's usePromotions/
 *     useProducts/useProduct/useCurrentBasket (via
 *     `@salesforce/retail-react-app/app/hooks/use-current-basket`). `disableAuthInit` +
 *     an `.invalid` proxy URL prevent any real network calls; none of this story's mock line
 *     items carry priceAdjustments/bundledProductItems/type.bundle, so every one of those
 *     hooks resolves with `enabled: false` and never actually fetches.
 *   CurrencyProvider — useCurrency (item-price.tsx, product-item/index.tsx itself).
 *   ServerContext.Provider (from `@salesforce/pwa-kit-react-sdk`, not commerce-sdk-react) —
 *     found live in Storybook, not anticipated: item-attributes.tsx's useCurrentBasket() call
 *     above has its own separate transitive chain (useSFPayments -> useAppOrigin -> useOrigin)
 *     that calls the SDK's useServerContext() and destructures `res` from it unconditionally.
 *     With no Provider, useContext returns undefined and the destructure throws before useOrigin's
 *     own `typeof window !== 'undefined'` branch (which never touches `res` at all) is reached.
 *     `value={{}}` matches exactly what the real app's own browser bootstrap supplies
 *     client-side (`ssr/browser/main.js`'s `OuterApp`) — confirmed by reading that file.
 *
 * `GiftCard` story (round 2 rework): renders `ProductItem` with the new `hideStepperAndActions`
 * prop (SFCC-270 round 2, session-notes.md §11.2) set to true, on a plausible mock line item —
 * NOT a real gift-card detection, which this build still cannot do (see index.tsx's own docblock;
 * unchanged finding from the prior round). This story demonstrates the capability half only:
 * that when a caller explicitly asks to hide the stepper/actions, neither renders.
 */
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { fn } from 'storybook/test';
import React from 'react';
import { MemoryRouter } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { CommerceApiProvider } from '@salesforce/commerce-sdk-react';
