describe('THROWAWAY: pre-existing stories never render a stray discount-label node', () => {
  beforeEach(() => {
    Object.defineProperty(window, 'matchMedia', {
      writable: true,
      value: vi.fn().mockImplementation((query: string) => ({
        matches: false,
        media: query,
        onchange: null,
        addListener: vi.fn(),
        removeListener: vi.fn(),
        addEventListener: vi.fn(),
        removeEventListener: vi.fn(),
        dispatchEvent: vi.fn(),
      })),
    });

    mockUseMultiSite.mockReturnValue({
      site: { id: 'ZimmermannAU' },
      buildUrl: (path: string) => path,
    });
  });

  test('Default story args render no zimm-discount-label node', () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    renderWithProviders(<ProductItem {...(Default.args as any)} />);
    expect(screen.queryByTestId('zimm-discount-label')).not.toBeInTheDocument();
  });

  test('MultipleItems story (its own render fn, both line items) renders no zimm-discount-label node', () => {
    // MultipleItems has no `args` of its own (only a custom `render`) — call that render fn
    // directly, exactly matching what Storybook itself would render for this story beyond the
    // two hardcoded `product`/`primaryAction` overrides inside it.
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    renderWithProviders((MultipleItems.render as any)({}));
    expect(screen.queryByTestId('zimm-discount-label')).not.toBeInTheDocument();
  });

  test('GiftCard story args render no zimm-discount-label node', () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    renderWithProviders(<ProductItem {...(GiftCard.args as any)} />);
    expect(screen.queryByTestId('zimm-discount-label')).not.toBeInTheDocument();
  });
});
